var zmq = require('zeromq');
var sock = zmq.socket('router');

sock.bindSync('tcp://127.0.0.1:57503');
console.log('Worker (router) bound to port 57503');

sock.on('message', function(identity, msg) {
  console.log('Received work from identity %s: %s', identity.toString(), msg.toString());

  // Optionally reply to the sender
  sock.send([identity, 'Acknowledged']);
});
